def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n < 3:
        return 'C'

    my_last, opp_last = history[-1]

    opp_c = 0
    my_c = 0
    for me, opp in history:
        if me == 'C':
            my_c += 1
        if opp == 'C':
            opp_c += 1
    opp_d = n - opp_c
    my_d = n - my_c
    opp_rate = opp_c / float(n)

    w10 = min(n, 10)
    r10_c = 0
    for i in range(n - w10, n):
        if history[i][1] == 'C':
            r10_c += 1
    r10_rate = r10_c / float(w10)

    w20 = min(n, 20)
    r20_c = 0
    for i in range(n - w20, n):
        if history[i][1] == 'C':
            r20_c += 1
    r20_rate = r20_c / float(w20)

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    uf = 0
    up = 0
    resp_c = 0
    resp_d = 0
    start = max(1, n - 25)
    for i in range(start, n):
        prev_my, prev_opp = history[i - 1]
        curr_opp = history[i][1]
        if prev_my == 'D':
            if curr_opp == 'C':
                resp_c += 1
            else:
                resp_d += 1
            if prev_opp == 'C':
                if curr_opp == 'C':
                    uf += 1
                else:
                    up += 1

    forgive_enough = False
    if up == 0 and uf >= 1:
        forgive_enough = True
    elif uf >= 2 and uf >= 3 * up:
        forgive_enough = True

    can_exploit = (
        forgive_enough
        and resp_c >= resp_d
        and opp_rate > 0.60
        and opp_d < n * 0.55
        and r20_rate > 0.55
        and r10_rate > 0.50
    )

    if opp_d == 0 and my_d == 0:
        if (n == 18 or n == 64) and rng.random() < 0.18:
            return 'D'

    if my_last == 'D' and opp_last == 'C':
        if can_exploit:
            return 'D'
        if opp_rate > 0.45:
            return 'C'
        return 'D'

    if opp_last == 'C':
        if can_exploit:
            return 'D'
        return 'C'

    if my_last == 'C':
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            if opp_rate > 0.30:
                return 'C'
            return 'D'
        if n < 12:
            return 'D'
        if opp_rate > 0.85 and opp_d_streak == 1 and rng.random() < 0.10:
            return 'C'
        return 'D'

    if my_last == 'D' and opp_last == 'D':
        if opp_rate > 0.18 and r10_c > 0:
            peace_fail = 0
            for i in range(max(1, n - 15), n):
                if (
                    history[i - 1][0] == 'D'
                    and history[i][0] == 'C'
                    and history[i - 1][1] == 'D'
                    and history[i][1] == 'D'
                ):
                    peace_fail += 1

            if peace_fail < 2 and (my_d_streak >= 2 or opp_d_streak >= 3):
                if rng.random() < 0.35:
                    return 'C'
                return 'D'

            if opp_rate > 0.25 and my_d_streak >= 5:
                if rng.random() < 0.12:
                    return 'C'

        return 'D'

    return 'C'
